import java.util.List;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.Test;
import org.springframework.boot.test.context.SpringBootTest;

import com.vaadin.browserless.SpringBrowserlessTest;
import com.vaadin.flow.component.button.Button;
import com.vaadin.flow.component.html.H1;
import com.vaadin.flow.component.html.ListItem;
import com.vaadin.flow.component.html.Span;
import com.vaadin.flow.component.textfield.TextField;

@SpringBootTest
class ItemsViewTest extends SpringBrowserlessTest {

    @Test
    void addItem_appendsItemAndUpdatesCount() {
        navigate(ItemsView.class);

        addItem("Milk");
        addItem("Eggs");

        List<ListItem> items = $(ListItem.class).all();
        Assertions.assertEquals(2, items.size());
        Assertions.assertEquals("Milk", items.get(0).getText());
        Assertions.assertEquals("Eggs", items.get(1).getText());
        Assertions.assertEquals("Items: 2", countText());
        Assertions.assertEquals("", field().getValue());
    }

    @Test
    void addItem_sameTextTwice_addsTwoItems() {
        navigate(ItemsView.class);

        addItem("Milk");
        addItem("Milk");

        Assertions.assertEquals(2, $(ListItem.class).all().size());
        Assertions.assertEquals("Items: 2", countText());
    }

    @Test
    void addItem_blankValue_addsNothingAndMarksFieldInvalid() {
        navigate(ItemsView.class);

        addItem("   ");

        Assertions.assertEquals(0, $(ListItem.class).all().size());
        Assertions.assertEquals("Items: 0", countText());
        Assertions.assertTrue(field().isInvalid());
    }

    @Test
    void clear_removesAllItemsAndCanAddAgain() {
        navigate(ItemsView.class);
        addItem("Milk");
        addItem("Eggs");

        test($(Button.class).withText("Clear").single()).click();

        Assertions.assertEquals(0, $(ListItem.class).all().size());
        Assertions.assertEquals("Items: 0", countText());

        addItem("Bread");
        Assertions.assertEquals(1, $(ListItem.class).all().size());
        Assertions.assertEquals("Items: 1", countText());
    }

    @Test
    void view_hasExpectedStructure() {
        navigate(ItemsView.class);

        Assertions.assertEquals("Items", $(H1.class).single().getText());
        Assertions.assertTrue(field().isEmpty());
        Assertions.assertTrue($(Button.class).withText("Add").single().isEnabled());
        Assertions.assertTrue($(Button.class).withText("Clear").single().isEnabled());
        Assertions.assertEquals("Items: 0", countText());
    }

    private void addItem(String value) {
        test(field()).setValue(value);
        test($(Button.class).withText("Add").single()).click();
    }

    private TextField field() {
        return $(TextField.class).withLabel("Item").single();
    }

    private String countText() {
        return $(Span.class).single().getText();
    }

}
